export default class extends BridgeComponent {
  static component = "share"

  shareUrl() {
    const description = this.#formatDescription(this.bridgeElement.bridgeAttribute("share-description"))
    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: description
    })
  }
  #formatDescription(description) {
    if (!description) return description

    try {
      const data = JSON.parse(description)
      if (data.type === "card") {
        const added = formatLocalTime(data.created_at, "short_date")
        const updated = formatLocalTime(data.last_active_at, "short_date")
        return `Added ${added} by ${data.author} and ${data.assignees}. Updated ${updated}`
      }
    } catch {
      return description
    }

    return description
  }
}


