const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000
const CALENDAR_DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/

const TIME_FORMATTER = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" })
const SHORT_DATE_FORMATTER = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const FULL_DATE_FORMATTER = new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit", year: "numeric" })
const WEEKDAY_DATE_FORMATTER = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const NUMERIC_DATE_TIME_FORMATTER = new Intl.DateTimeFormat("en-US", {
  month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
})
const YEAR_DATE_FORMATTER = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" })

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY_IN_MILLISECONDS)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(value, format) {
  const date = parseLocalDateTime(value)

  if (Number.isNaN(date.getTime())) return value

  switch (format) {
    case "relative":
      return formatRelativeDate(date)
    case "short_date":
      return formatShortDate(date)
    case "full_date":
      return FULL_DATE_FORMATTER.format(date)
    case "weekday_date":
      return WEEKDAY_DATE_FORMATTER.format(date)
    case "time":
      return TIME_FORMATTER.format(date)
    case "numeric_date_time":
      return NUMERIC_DATE_TIME_FORMATTER.format(date)
    default:
      return value
  }
}

function parseLocalDateTime(value) {
  const match = value.match(CALENDAR_DATE_PATTERN)

  if (match) {
    const [, year, month, day] = match.map(Number)
    return new Date(year, month - 1, day)
  }

  return new Date(value)
}

function formatRelativeDate(date) {
  const daysAgo = signedDifferenceInDays(date, new Date())

  if (daysAgo === 0) {
    return TIME_FORMATTER.format(date)
  } else if (daysAgo === 1) {
    return "yesterday"
  } else if (daysAgo === -1) {
    return "tomorrow"
  } else if (daysAgo > 1 && daysAgo < 7) {
    return `${daysAgo} days ago`
  } else if (daysAgo < -1 && daysAgo > -7) {
    return `in ${Math.abs(daysAgo)} days`
  } else {
    return formatShortDate(date)
  }
}

function formatShortDate(date) {
  if (date.getFullYear() === new Date().getFullYear()) {
    return SHORT_DATE_FORMATTER.format(date)
  } else {
    return YEAR_DATE_FORMATTER.format(date)
  }
}
